\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  163\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -197\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Vocabularium biblicum}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u220 \'dcberschrift am oberen Blattrand abgeschnitten.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24  Vocabula Ysaie\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ethnicus id est gentilis; emulus id est inimicus}}\plain \f1\lang1033\fs24  ... \endash ... (165\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  vehiculum ad portandum misper\plain \f1\lang1033\fs24   (?).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (165\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Vocabula Genesis\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Primus liber biblie dicitur genesis grece, presit hebraice, generacio celi eo (!) terre latine. Abyssus est profunditas aquarum}}\plain \f1\i\lang1033\fs24   et dicitur ab a, quod est sine, et bissus purpura\plain \f1\lang1033\fs24  ...;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (168\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Vocabula Exodi\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Secundus liber biblie est trinomius. Dicitur enim exodus grece}}\plain \f1\i\lang1033\fs24 , hellesmoth hebraice, exitus latine. Ingruo id est insto, vnde\plain \f1\lang1033\fs24 :\plain \f1\i\lang1033\fs24   Si ingruerit bellum id est insteterit vel occurrerit\plain \f1\lang1033\fs24  ...;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (172\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Vocabula Leuitici etc.\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Liber tercius dicitur leuiticus grece et vagetra hebrayce et offertorius siue sacerficatorius latine}}\plain \f1\lang1033\fs24\chcbpat17 . {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Arcus }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 (!)}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  quarte declinacionis est membrum}}\plain \f1\lang1033\fs24  ...;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0  (195\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Vocabula Canticulorum\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Fragrancia id est indulencia (!). V[ersus]: Fla facit ardentem, sed fi an designat odorem}}\plain \f1\lang1033\fs24   (aus: Eberhardus Bethuniensis, Graecismus; Ed.: Johannes \plain \f1\scaps\lang1033\fs24 Wrobel\plain \f1\lang1033\fs24   (Hrsg.): Eberhardus Bethuniensis, Graecismus. Hildesheim u.a. 1987 (Neudruck der Ausgabe Breslau 1887), Kap. XV, Vers 69, S. 154) ...;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (196\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Vocabula Sapiencie\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Maliuola, id est anima mala volens}}\plain \f1\lang1033\fs24  ...;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (196\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Vocabula Ecclesiastici\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Peritos penultima producta (197ra) est doctusy}}\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24 ... \endash ... \plain \f1\i\lang1033\fs24  abdo, id est abscondo et cetera etcetera\plain \f1\lang1033\fs24 . >{\field{\*\fldinst HYPERLINK "hida://5650[7].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Expliciunt vocabula Biblie per manus Alberti Gerad anno domini M\u176 \'b0 CCC\u176 \'b0 LXXXXV\u176 \'b0 in vigilia Annunciacionis Marie (24. M\u228 \'e4rz) virginis hora vesperorum}}\plain \f1\lang1033\fs24  <.
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 Worterkl\u228 \'e4rungen zu Isaias, zu Genesis bis Sirach, z.T. auch zu den entsprechenden Prologen des Hieronymus; Abfolge: Genesis bis II Paralipomenon, dann Psalmen, dann Ezras bis Sirach (ohne Psalmen). Die Anordnung der W\u246 \'f6rter entspricht ihrer Abfolge im Bibeltext. \u214 \'d6fter werden bei der Worterkl\u228 \'e4rung Verse hinzugezogen, u.a. aus: Physiologus; Boethius, De consolatione philosophiae; Eberhardus Bethuniensis, Graecismus; Alexander de Villa Dei, Doctrinale; Johannes de Garlandia, Synonyma. Verschiedentlich werden auch die deutschen \u220 \'dcbersetzungen der W\u246 \'f6rter angegeben.  }

