\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Sanftl\plain \f1\lang1033\fs20   I, p. 631; Albert \plain \f1\scaps\lang1033\fs20 Boeckler\plain \f1\lang1033\fs20 , Die Regensburg-Pr\u252 \'fcfeninger Buchmalerei des XII. und XIII. Jahrhunderts. M\u252 \'fcnchen 1924 (Miniaturen aus Handschriften der Bayerischen Staatsbibliothek in M\u252 \'fcnchen 8), S. 82 und S. 122; \plain \f1\scaps\lang1033\fs20 Klemm\plain \f1\lang1033\fs20 , Rom. Hss. 1, Nr. 10, S. 19f.; Peter \plain \f1\scaps\lang1033\fs20 Schmidt\plain \f1\lang1033\fs20 , Gedruckte Bilder in handgeschriebenen B\u252 \'fcchern. Zum Gebrauch von Druckgraphik im 15. Jahrhundert. K\u246 \'f6ln u.a. 2003, S. 214 und Anm. 43, S. 367.}

