\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -32\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Musica et scolica enchiriadis (cum glossis)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -11\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Musica enchiriadis: \plain \f3\i\lang1024\fs24 Incipivnt qv\u281 \'eadam \plain \f1\i\lang1033\fs24  vtiliora de arte musica\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Scolica enchiriadis\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  liber I\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f3\i\lang1024\fs24\chcbpat17 Sicut uocis articulat\u281 \'ea elementari\u281 \'ea atque indiuidu\u281 \'ea [letztes u korr.] partes sunt litter\u281 \'ea}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f3\i\lang1024\fs24 Huiusc\u281 \'ea ratiuncul\u281 \'ea ponamus hic finem\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Explicit liber primus scolic\plain \f3\i\lang1024\fs24 \u281 \'ea\plain \f1\lang1033\fs24   (dazu am Rand: \plain \f1\i\lang1033\fs24  id est exercicia que fiunt in scola\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  enchiriadis de mvsica\plain \f1\lang1033\fs24  ; (11\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -32\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Scolica enchiriadis: \plain \f1\i\lang1033\fs24  Incipit\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  liber secundus eivsdem\plain \f1\lang1033\fs24 . \plain \f2\i\lang1032\fs24 \u916 \'c4 \plain \f1\lang1033\fs24  (= discipulus): {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Musica quid est?}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  M\plain \f1\lang1033\fs24   (= magister): \plain \f1\i\lang1033\fs24  Bene modulandi\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  scientia \plain \f1\lang1033\fs24  \u8230 \'85 \u8210 ? (16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24  maximam suauitatem cantilenis adiciet\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Finit pars prima\plain \f2\lang1032\fs24 . \plain \f2\i\lang1032\fs24 Incipit secunda\plain \f2\lang1032\fs24 . [\u916 \'c4]: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Symphonia quid est?}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? (22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24  ducatu perueniam\plain \f1\lang1033\fs24  ; (am Rand, 15. Jh.,: \plain \f1\i\lang1033\fs24  Finit\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  pars secundam\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Incipit tercia\plain \f1\lang1033\fs24 ) \plain \f2\i\lang1032\fs24 \u916 \'c4\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Rogo inprimis edicas}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  retinet modum\plain \f1\lang1033\fs24  ; zahlreiche Diagramme; gelegentlich Interlinear- und vor allem Randglossen (auch Korrekturen und Texterg\u228 \'e4nzungen, z. B. 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
