\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  146\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -199\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Smaragdus Sancti Michaelis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Diadema monachorum}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (146\plain \f1\super\lang1033\fs24 ra-b\plain \f1\lang1033\fs24 ) Prolog: >\plain \f1\i\lang1033\fs24  Incipit prologus in dyadema monachorum\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hunc modicum operis nostri libellum}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  capitulum primum ponimus\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24  Explicit prologus\plain \f1\lang1033\fs24  <; (146\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  -195\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Incipit liber\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  Smaragdi qui dicitur dyadema monachorum\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Incipit capitulum primum de oratione\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hoc est remedium eius qui uiciorum temptamentis estuat}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  hoc abierunt uacui nichil habentes\plain \f1\lang1033\fs24   (Schluss von c. XLIII im Druck); weitere sechs nicht zum Text geh\u246 \'f6rende Kapitel angeh\u228 \'e4ngt:  (195\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -196\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De commendacione caritatis\plain \f1\lang1033\fs24  < (daneben \plain \f1\i\lang1033\fs24  91\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Fratres karissimi}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  quam ipsi eis coronam fabricant eternam\plain \f1\lang1033\fs24  ; (196\plain \f1\super\lang1033\fs24 rb-vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De humilitate et obedientia\plain \f1\lang1033\fs24  < (\plain \f1\i\lang1033\fs24  92\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Credendus est quod nunquam caritas}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  ad eternum gaudium perducit\plain \f1\lang1033\fs24  ; (196\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  -197\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De uirtute\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  continencie\plain \f1\lang1033\fs24  < (\plain \f1\i\lang1033\fs24  93\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sciendum est, fratres, quod uirtus continencie non solum est in cibo}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  et in abstinentia proficere studete\plain \f1\lang1033\fs24  ; (197\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  -198\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De continencia locucionis\plain \f1\lang1033\fs24  < (\plain \f1\i\lang1033\fs24  94\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hortor uos etiam, fratres, ut in locucione sitis continentes}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  et multa mala deuitantur\plain \f1\lang1033\fs24  ; (198\plain \f1\super\lang1033\fs24 ra-vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De continencia uestium et ciborum\plain \f1\lang1033\fs24  < (\plain \f1\i\lang1033\fs24  95\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Iohannes Baptista primus noui testamenti monachus pilis camelorum uestitus}}\plain \f1\i\lang1033\fs24   fuisse legitur\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  congruunt necessaria ministretis\plain \f1\lang1033\fs24  ; (198\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  -199\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De gratia compunctionis\plain \f1\lang1033\fs24  < (\plain \f1\i\lang1033\fs24  96\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Et quia compunctio omni utilis tempore nobis est}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  per hanc dominus ad misericordiam prouocatur\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24  Explicit dyadema monachorum\plain \f1\lang1033\fs24  <; nachtr\u228 \'e4gliche arabische Z\u228 \'e4hlung der Kapitel.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 Druck: PL 102, 593-689, diese Hs. h\u228 \'e4ufig stark abweichend, cc. LX, LXIX, LXXII, LXXXI, LXXXII, LXXXVIII, LXXXIX, XCI, XCII, XCIII, XCVI, C der Druckausgabe fehlen; zum Werk und seinen Quellen vgl. Fidel \plain \f1\scaps\lang1033\fs20 R\plain \f1\scaps\lang1033\fs20 \u228 \'e4\plain \f1\scaps\lang1033\fs20 dle\plain \f1\lang1033\fs20 , Studien zu Smaragd von Saint-Mihiel. M\u252 \'fcnchen 1974 (Medium Aevum 29), S. 68-75. \u8210 ? Vgl. Willibrord \plain \f1\scaps\lang1033\fs20 Witters\plain \f1\lang1033\fs20 , Smaragde au Moyen \u194 \'c2ge. La diffusion de ses \u233 \'e9crits d\rquote apr\u232 \'e8s la traduction manuscrite, in: \u201 \'c9tudes lig\u233 \'e9riennes d\rquote histoire et d\rquote arch\u233 \'e9ologie m\u233 \'e9di\u233 \'e9vales. M\u233 \'e9moires et expos\u233 \'e9s pr\u233 \'e9sent\u233 \'e9s \u224 \'e0 la semaine d\rquote \u233 \'e9tudes m\u233 \'e9di\u233 \'e9vales de Saint-Benoit-sur-Loire du 3 au 10 juillet 1969, hrsg. von Ren\u233 \'e9 \plain \f1\scaps\lang1033\fs20 Louis\plain \f1\lang1033\fs20   / Pierre \plain \f1\scaps\lang1033\fs20 Rousseau\plain \f1\lang1033\fs20 . Paris 1975 (Cahiers d\rquote arch\u233 \'e9ologie et d\rquote histoire 4), S. 361-376, hierzu S. 364f. \u8210 ? \plain \f1\scaps\lang1033\fs20 Bloomfield\plain \f1\lang1033\fs20   (und Suppl.) 2456.}

