\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Odo Magdunensis}}\plain \f1\b\lang1033\fs24   (\u8218 \'82Macer Floridus\rquote ): {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De viribus herbarum (mit deutschen Pflanzennamen)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24  De artemisia\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Herbarum quasdam dicturus carmine uires}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  Vna diagridii sic\plain \f1\lang1033\fs24   [folgendes \plain \f1\i\lang1033\fs24  est\plain \f1\lang1033\fs24   durch Unterpunktion getilgt] \plain \f1\i\lang1033\fs24  apta solutio faciet\plain \f1\lang1033\fs24   (\plain \f1\i\lang1033\fs24  diagridii\plain \f1\lang1033\fs24   am Rand vermerkt); Bestand nach der Edition von Ludwig \plain \f1\scaps\lang1033\fs24 Choulant\plain \f1\lang1033\fs24   (s. unten): capp. I\u8210 ?VIII (58\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , cap. VI nach v. 241 in zwei Kapitel geteilt, >\plain \f1\i\lang1033\fs24  De minori plantagine\plain \f1\lang1033\fs24  <, daneben \plain \f1\i\lang1033\fs24  \u183 \'b77\u183 \'b7\plain \f1\lang1033\fs24 ), XII, XIII, XV, XVII, XX\u8210 ?XXIV (63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , v. 808 am Ende von cap. XXI; 64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , in cap. XXIII vv. 869, 868 nach v. 863), XLIV, XLV, LXV, (65\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -66\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   unterer Rand, zwei Kolumnen) XLVII, XXXIII (66\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   unterer Rand cap. XXXIII aus anderer Vorlage wiederholt: \plain \f1\i\lang1033\fs24  Decepti \plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24  medici non hec sentire\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  uidentur\plain \f1\lang1033\fs24   \u8230 \'85), XXXV, XXXVII, XXXIX, XXVII, XXIX, XXXII (68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , in f\u252 \'fcnf Kapitel geteilt), XL, LIII, LIX, XLI (71\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 , in drei Kapitel geteilt), X, XIV, IX, XXV, XVIII (74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , nach v. 738 in zwei Kapitel geteilt), XI, XIX, XXVI, XXVIII, XXX, XXXI (77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , v. 1036 am Rand nachgetragen), XXXIV (77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , \u220 \'dcberschrift am Rand querst\u228 \'e4ndig nachgetragen: \plain \f1\i\lang1033\fs24  De boglossa\plain \f1\lang1033\fs24   ?, dazu von sp\u228 \'e4terer Hand: \plain \f1\i\lang1033\fs24  De ohsenzvnge\plain \f1\lang1033\fs24 ), XXXVIII, XLII, XLIII, XLVI, LVI, LVII, XLVIII\u8210 ?LII, LV, LVIII (vv. 1892\u8210 ?1902 fehlen), LX\u8210 ?LXII, XVI (85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , vv. 681\u8210 ?684 aus cap. XVII angeh\u228 \'e4ngt, endet \u8230 \'85 \plain \f1\i\lang1033\fs24  recenti\plain \f1\lang1033\fs24 ), LIV, LXIII, LXIV, LXVI (86\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , bricht nach zweitem v. 2057 ab, wegen Blattverlust, s. oben; Reklamante unten verweist auf v. 2058: \plain \f1\i\lang1033\fs24  vsus medendi\plain \f1\lang1033\fs24  ; nach der sp\u228 \'e4tmittelalterlichen arabischen Z\u228 \'e4hlung fehlen zwei Kapitel vollst\u228 \'e4ndig, wohl capp. LXVII u. LXVIII), LXIX (87\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , nur die letzten f\u252 \'fcnf Verse ab v. 2120 wegen Blattverlust), LXX\u8210 ?LXXVII (88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , cap. LXXV ab v. 2200 in zwei Kapitel geteilt);
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \u8218 \'82Spuria Macri\rquote  (von Glossenhand nachgetragen): (84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   unterer Rand, in zwei Kolumnen) \plain \f1\i\lang1033\fs24  De\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  Pentafilos idest\plain \f1\lang1033\fs24   (?) \plain \f1\i\lang1033\fs24  V foliis\plain \f1\lang1033\fs24   (= Quinquefoliis). {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Herbam Pentafilos Greci nostrique fatentur}}\plain \f1\lang1033\fs24   / \u8230 \'85; (85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   unterer Rand, zwei Kolumnen): \plain \f1\i\lang1033\fs24  De Algarica\plain \f1\lang1033\fs24   (= agaricus). {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Algerici species gemine sunt, ipsa probat res}}\plain \f1\lang1033\fs24   / \u8230 \'85; (89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Liquiritia (8 Verse): {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Multas nam uere Liquiricis habere}}\plain \f1\lang1033\fs24   / \u8230 \'85; \plain \f1\i\lang1033\fs24  De Sambucho\plain \f1\lang1033\fs24   (am Rand). {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Svnt gradibus primis sicci calidique secundis}}\plain \f1\lang1033\fs24   / \plain \f1\i\lang1033\fs24  Sambuchi sunt soluentes\plain \f1\lang1033\fs24   \u8230 \'85 \plain \f1\i\lang1033\fs24  Sepe me\plain \f1\lang1033\fs24  [lancho]\plain \f1\i\lang1033\fs24  licos\plain \f1\lang1033\fs24   [? durch Rasur schlecht korr.] \plain \f1\i\lang1033\fs24  et flegme purgat humores\plain \f1\lang1033\fs24  ; darunter von anderer Hand: \plain \f1\i\lang1033\fs24  In hoc libro sunt C herb\plain \f1\lang1033\fs24  [e minus] (? Pergament abgeschabt) \plain \f1\i\lang1033\fs24  decem\plain \f1\lang1033\fs24   (dar\u252 \'fcber \plain \f1\i\lang1033\fs24  \u183 \'b7X\u183 \'b7\plain \f1\lang1033\fs24 ); am oberen Rand zwei verblasste Zeilen, untere Zeile beginnt \plain \f1\i\lang1033\fs24  Ex hiis fiet\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  aqua que lumina reddit\plain \f1\lang1033\fs24   \u8230 \'85;
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 Fremdgut: (86\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De castoreo\plain \f1\lang1033\fs24  < (daneben: \plain \f1\i\lang1033\fs24  pibergail\plain \f1\lang1033\fs24   und Kapitelzahl \plain \f1\i\lang1033\fs24  74\plain \f1\lang1033\fs24  ; 23 Verse) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nunc quicumque cupis cuius depellere morbum}}\plain \f1\lang1033\fs24   / \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  Sic currens demum conscendens ad\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  duodenum\plain \f1\lang1033\fs24  ; (89\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) Versus de urina aus Regimen sanitatis Salernitanum pars VI, c. XXIII,11 (3 Verse): \plain \f1\i\lang1033\fs24  Et\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  reor urinis calor estat\plain \f1\lang1033\fs24   [viell. bei \plain \f1\i\lang1033\fs24  s\plain \f1\lang1033\fs24   x hineinkorr.] \plain \f1\i\lang1033\fs24  causa ruboris\plain \f1\lang1033\fs24   (dar\u252 \'fcber Kapitelzahl \plain \f1\i\lang1033\fs24  88\plain \f1\lang1033\fs24 ) /\u8230 \'85; XXII, 12 (2 Verse): \plain \f1\i\lang1033\fs24  Cvilibet urine si sanguis inundat abunde\plain \f1\lang1033\fs24    /\u8230 \'85; >\plain \f1\i\lang1033\fs24  De semperviua\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 De semperuiue succo}}\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  cocleaua \plain \f1\lang1033\fs24  (?) \plain \f1\i\lang1033\fs24  bina\plain \f1\lang1033\fs24   / \u8230 \'85 \plain \f1\i\lang1033\fs24  Hoc medicamentum surd\plain \f1\lang1033\fs24  [i]\plain \f1\i\lang1033\fs24  s est auribus aptum\plain \f1\lang1033\fs24  ; hinzugef\u252 \'fcgt von sp\u228 \'e4terer Hand: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Fonti pedes loti, calido rasi sale foti}}\plain \f1\lang1033\fs24 , / \plain \f1\i\lang1033\fs24  Clarificat lumen\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  exaltat uocis acumen\plain \f1\lang1033\fs24   (vgl. \plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Proverbia 9728); es folgen einige getilgte Zeilen (s. oben Herkunft), die von einem Besitzeintrag, 18. Jh., \u252 \'fcberschrieben wurden (s. oben); zu den darunter stehenden Versen (Liquiritia) s. oben \u8218 \'82Spuria Macri\lquote ; (89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   linker Rand) lat.-mhd. Glossar der Kr\u228 \'e4uternamen (Spalte mit lat. Namen teilweise abgerieben) von Hand des 13. Jh.s eingetragen (wohl gleiche Hand auch am oberen Rand von 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  fungus \u183 \'b7swam\u183 \'b7\plain \f1\lang1033\fs24 ): \plain \f1\i\lang1033\fs24  abs\plain \f1\lang1033\fs24  [in]\plain \f1\i\lang1033\fs24  thium\plain \f1\lang1033\fs24   \endash  \plain \f1\i\lang1033\fs24  wermvt\plain \f1\lang1033\fs24   \u8230 \'85 [g]\plain \f1\i\lang1033\fs24  ariofilus \plain \f1\lang1033\fs24  \endash  \plain \f1\i\lang1033\fs24  negelin\plain \f1\lang1033\fs24  ; darunter von vermutlich anderer Hand [s]\plain \f1\i\lang1033\fs24  ambucus\plain \f1\lang1033\fs24   \endash  \plain \f1\i\lang1033\fs24  hol\plain \f1\lang1033\fs24  [..]\plain \f1\i\lang1033\fs24  r\plain \f1\lang1033\fs24   (? zu vermuten ist \plain \f1\i\lang1033\fs24  holter\plain \f1\lang1033\fs24 , s. unten); von sp\u228 \'e4terer Hand, 14. Jh., erg\u228 \'e4nzt (nicht identisch mit dt. Glossenhand im Text): \plain \f1\i\lang1033\fs24  Elobor\plain \f1\lang1033\fs24   (= elleborum, -us) \plain \f1\i\lang1033\fs24  album\plain \f1\lang1033\fs24   \endash  \plain \f1\i\lang1033\fs24  haemschwrtz\plain \f1\lang1033\fs24   / \plain \f1\i\lang1033\fs24  Elobor nigrvm\plain \f1\lang1033\fs24   \endash  \plain \f1\i\lang1033\fs24  stainwrtz\plain \f1\lang1033\fs24   / \plain \f1\i\lang1033\fs24  Ebolus\plain \f1\lang1033\fs24   \endash  \plain \f1\i\lang1033\fs24  attisch\plain \f1\lang1033\fs24  ; v\u246 \'f6llig verblasst bzw. abgerieben: \plain \f1\i\lang1033\fs24  Boglossa\plain \f1\lang1033\fs24   \endash  \plain \f1\i\lang1033\fs24  ochsenzung\plain \f1\lang1033\fs24   (?) \plain \f1\i\lang1033\fs24  \u183 \'b751\plain \f1\lang1033\fs24  \u183 \'b7 (Kapitelzahl im Text = cap. XXXIV, 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , s. oben) / \plain \f1\i\lang1033\fs24  Origanum\plain \f1\lang1033\fs24   (?) \endash  \plain \f1\i\lang1033\fs24  tost\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  \u183 \'b752\u183 \'b7\plain \f1\lang1033\fs24   / \plain \f1\i\lang1033\fs24  asarus\plain \f1\lang1033\fs24   (?) \plain \f1\i\lang1033\fs24  \u183 \'b755\u183 \'b7\plain \f1\lang1033\fs24  ; darunter unleserliche Textzeile;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 88 Kapitel nach hinzugef\u252 \'fcgter sp\u228 \'e4tmittelalterlicher arabischer Z\u228 \'e4hlung; am Rand zu einzelnen Kr\u228 \'e4uterkapiteln im Text vorkommende medizinisch relevante Termini (Nennungen von K\u246 \'f6rperteilen und Krankheitsbildern) sowie gelegentliche Erl\u228 \'e4uterung von etwa gleichzeitiger Hand; ab cap. II (55\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  >\plain \f1\i\lang1033\fs24  De aprotano\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  abraute\plain \f1\lang1033\fs24 ) meist dt. bzw. bair. Pflanzennamen (oft mehrere), teilweise auch lat. Bezeichnungen von Hand der 1. H\u228 \'e4lfte des 14. Jh.s hinzugef\u252 \'fcgt.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Bibliographische Notizen in violetter Tinte zum \u8218 \'82Macer\rquote  und seinem Autor von Hand des 18. Jh.s (dieselbe Hand wie Besitzeintr\u228 \'e4ge und Notizen zu Teil I, 54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , s. oben), angefangen auf 89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   am unteren Rand, erneut angesetzt auf folgender Seite (90\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Nachsatz, Papier).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 Edition/Druck: Macer Floridus de viribus herbarum \u8230 \'85, ed. Ludwig \plain \f1\scaps\lang1033\fs20 Choulant\plain \f1\lang1033\fs20 . Leipzig 1832; Nachdruck dieser Edition ohne Einleitung in H\u246 \'f6hepunkte der Klostermedizin. Der \u8222 \'84Macer Floridus\ldblquote  und das Herbarium des Vitus Auslasser, hrsg. mit Einl. u. dt. \u220 \'dcbersetzung von Johannes Gottfried \plain \f1\scaps\lang1033\fs20 Mayer\plain \f1\lang1033\fs20   / Konrad \plain \f1\scaps\lang1033\fs20 Goehl\plain \f1\lang1033\fs20 . Leipzig 2001; die \u8218 \'82Spuria Macri\rquote  dieser Hs. aus Friedrich Anton \plain \f1\scaps\lang1033\fs20 Reuss\plain \f1\lang1033\fs20 , Walafridi Strabi hortulus \u8230 \'85 Accedunt analecta ad antiquitates florae germanicae et capita aliquot Macri nondum edita. W\u252 \'fcrzburg 1834, S. 101-105 abgedruckt in Der deutsche \u8218 \'82Macer\rquote . Vulgatfassung. Mit einem Abdruck des lateinischen Macer Floridus \u8218 \'82De viribus herbarum\rquote , hrsg. von Bernhard \plain \f1\scaps\lang1033\fs20 Schnell\plain \f1\lang1033\fs20   in Zusammenarbeit mit William \plain \f1\scaps\lang1033\fs20 Crossgrove\plain \f1\lang1033\fs20 . T\u252 \'fcbingen 2003 (Texte und Textgeschichte 50), S. 475-479 (I, II, V, X); die von \plain \f1\scaps\lang1033\fs20 Choulant\plain \f1\lang1033\fs20   (S. 124-140) in seiner Ausgabe mit aufgenommenen \u8218 \'82Spuria Macri\rquote , die aber nicht in Clm 14597 vorkommen, ediert Ulrike \plain \f1\scaps\lang1033\fs20 Jansen\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20  Spuria Macri\plain \f1\lang1033\fs20 . Ein Anhang zu \plain \f1\i\lang1033\fs20  Macer\plain \f1\lang1033\fs20   \plain \f1\i\lang1033\fs20  Floridus\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20  De viribus herbarum\plain \f1\lang1033\fs20 . Einleitung, \u220 \'dcbersetzung, Kommentar. Berlin/Boston 2013 (Beitr\u228 \'e4ge zur Altertumskunde 314), S. 28 diese Hs. genannt; zu den weiteren \u8218 \'82Spuria Macri\lquote , darunter auch die in Clm 14597 enthaltenen (s. oben), vgl. ebd., S. 11f. und die \u220 \'dcbersicht (Tabelle 3) zu \u220 \'dcberlieferung und Drucken S. 360f.; Fremdgut \u8218 \'82De castoreo\rquote (86\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ) im Anhang zu Quintus Serenus, Liber medicinalis (\u8222 \'84Sequuntur XXVI versus, qui in aliis impressis codicibus desiderantur\u750 ?) bei Aulus Cornelius Celsus, Medicinae libri octo. Venedig 1528, p. 163f. gedruckt (z. T. abweichend, mehr Verse); parallel \u252 \'fcberliefert u. a. in Fulda, HuLB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 C 9}}\plain \f1\lang1033\fs20 , 63\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20   (beginnt \plain \f1\i\lang1033\fs20  Hunc quicumque\plain \f1\lang1033\fs20   \u8230 \'85) und Vatikanstadt, BAV, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Vat. lat. 11514}}\plain \f1\lang1033\fs20 , 39\plain \f1\super\lang1033\fs20 r-v\plain \f1\lang1033\fs20  ; zu den Versen aus dem Regimen sanitatis Salernitanum (89\plain \f1\super\lang1033\fs20 r-v\plain \f1\lang1033\fs20 ) vgl. \u8218 \'82Flos medicinae scholae Salerni\rquote  in: Collectio Salernitana ossia documenti inediti \u8230 \'85, hrsg. von Salvatore \plain \f1\scaps\lang1033\fs20 De Renzi\plain \f1\lang1033\fs20 . Bd. 5. Neapel 1859, S. 67; zum Vers auf 89\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20   vgl. Karl \plain \f1\scaps\lang1033\fs20 Sudhoff\plain \f1\lang1033\fs20 , Zum Regimen Sanitatis Salernitanum, in: Archiv f\u252 \'fcr Geschichte der Medizin 12 (1920), S. 149-180, hierzu S. 152 [3177]. \u8210 ? Die Reihenfolge der Kapitel dieser erweiterten Fassung stimmt teilweise mit den \u228 \'e4ltesten Macer-Hss. \u252 \'fcberein; vgl. dazu William C. \plain \f1\scaps\lang1033\fs20 Crossgrove\plain \f1\lang1033\fs20 , Zur Datierung des \u8218 \'82Macer Floridus\rquote , in: Licht der Natur. Medizin in Fachliteratur und Dichtung. Festschrift f\u252 \'fcr Gundolf Keil zum 60. Geburtstag, hrsg. von Josef \plain \f1\scaps\lang1033\fs20 Domes\plain \f1\lang1033\fs20   u. a. G\u246 \'f6ppingen 1994 (G\u246 \'f6ppinger Arbeiten zur Germanistik 585), S. 55-63, hierzu S. 58f.; vgl. auch {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 4583}}\plain \f1\lang1033\fs20 , 47\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -77\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20   (2. H\u228 \'e4lfte 12. Jh.; zur Reihenfolge vgl. Catalogus III, s.n. 3,1, S. 136). \u8210 ? Zum lat.-mhd. Glossar der Pflanzennamen (89\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ) vgl. \plain \f1\scaps\lang1033\fs20 Steinmeyer/Sievers\plain \f1\lang1033\fs20   4, S. 372 (die Lesung \u8222 \'84holer\ldblquote  f\u252 \'fcr \u8218 \'82sambucus\rquote  ist nicht gesichert, wahrscheinlicher \plain \f1\i\lang1033\fs20  holter\plain \f1\lang1033\fs20 , s. oben); dt. Pflanzennamen \endash  meist die sp\u228 \'e4ter den einzelnen Kr\u228 \'e4uterkapiteln hinzugef\u252 \'fcgten \u8210 ? in alphabetischer Reihenfolge der lat. Bezeichnungen bei \plain \f1\scaps\lang1033\fs20 Sanftl\plain \f1\lang1033\fs20   III, p. 1612; die in {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 14851}}\plain \f1\lang1033\fs20 , 61\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -104\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20   hinzugef\u252 \'fcgten mhd. Pflanzennamen (bei \plain \f1\scaps\lang1033\fs20 Steinmeyer/Sievers\plain \f1\lang1033\fs20   4, S. 366f. Nr. MXXXVII\plain \f1\super\lang1033\fs20 a\plain \f1\lang1033\fs20 ) dienten offensichtlich nicht als Vorlage f\u252 \'fcr die nachgetragenen dt. Namen dieser Hs. \u8210 ? \u196 \'c4hnliche Ausf\u252 \'fchrungen wie in den bibliographischen Notizen des 18. Jh.s (89\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  -90\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ) bei \plain \f1\scaps\lang1033\fs20 Sanftl\plain \f1\lang1033\fs20   III, p. 1611 zum \u8218 \'82Macer\rquote  im Clm 14851. \u8210 ? Zum lat. \u8218 \'82Macer\rquote , der nun Odo von Meung (= Meung-sur-Loire) zugeschrieben wird, und den dt. Glossen vgl. William C. \plain \f1\scaps\lang1033\fs20 Crossgrove\plain \f1\lang1033\fs20 , in: \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20  VL 5 (1985), Sp. 1109-1116, hierzu Sp. 1109f.; LexMA 6 (1993), Sp. 1360 (Gundolf \plain \f1\scaps\lang1033\fs20 Keil\plain \f1\scaps\lang1033\fs20 )\plain \f1\lang1033\fs20 . \plain \f1\lang1033\fs24     }

