\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -116\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Commentarius in Apocalypsim}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Inter reliquos noui testamenti libros uocatur iste prophetia}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Sed aliis elongantior \plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24  prophetiis\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  quia quod illi cernebant a longe uenturum\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  Gratia domini nostri Iesu\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  id est remissio\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  peccatorum data a Iesu Christo\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Cum omnibus nobis et haec sit cum amen\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  id est cum\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  affirmatione\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Explicit liber\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 Parallel \u252 \'fcberliefert in Schaffhausen, MinisterialB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Min. 80}}\plain \f1\lang1033\fs20 , 8\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  -93\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  ; danach bei \plain \f1\scaps\lang1033\fs20 Stegm\plain \f1\scaps\lang1033\fs20 \u252 \'fc\plain \f1\scaps\lang1033\fs20 ller\plain \f1\lang1033\fs20 , RB 7, 11066.}

