\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 H\u281 ec oratio dominica dicitur, eo quia dominus eam conposuit}}\plain \f1\lang1033\fs24   \u8230 \'85 \plain \f1\i\lang1033\fs24  Pater noster\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Pater dicitur quia habet filium et pater dicitur a patrando hoc est a generando}}\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  Ipse autem nos a\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  cunctis malis eripere dignetur\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  qui cum deo patre\plain \f1\lang1033\fs24    \u8230 \'85 \plain \f1\i\lang1033\fs24  Amen\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Amen \plain \f1\lang1033\fs24  \u8218 \'82\plain \f1\i\lang1033\fs24  uere\plain \f1\lang1033\fs24  \lquote \plain \f1\i\lang1033\fs24   siue \plain \f1\lang1033\fs24  \u8218 \'82\plain \f1\i\lang1033\fs24  fideliter\plain \f1\lang1033\fs24  \lquote  \plain \f1\i\lang1033\fs24  interpretatur et aliquando fiat\plain \f1\lang1033\fs24 .}

