\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Sanftl II, \plain \f1\lang1033\fs20  p\plain \f1\scaps\lang1033\fs20 . 804, 826\plain \f1\lang1033\fs20 . \endash  MBK IV/1, S. 122 Anm. 218.}

