\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Nomina monachorum pro distributione librorum anno 1501}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\i\lang1033\fs24  Distributio librorum in die cinerum\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Dominus abbas Erasmus\plain \f1\lang1033\fs24  ... \endash ... \plain \f1\i\lang1033\fs24  frater Castulus\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Anno domini millesimo quingentesimo primo\plain \f1\lang1033\fs24 . Von Menger geschriebene Liste der St. Emmeramer M\u246 \'f6nche aus dem Jahr 1501, an den R\u228 \'e4ndern sind die Sterbejahre nachgetragen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red224\green224\blue224;\red255\green204\blue153;}

\uc1
\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20  Wasserzeichen: Ochsenkopf mit einkonturiger Stange und Beizeichen, dar\u252 \'fcber weiteres, nicht genauer bestimmbares Beizeichen, nicht nachweisbar. Lagen: (V + 2)\plain \f1\super\lang1033\fs20 142 \plain \f1\lang1033\fs20 . (132\plain \f1\super\lang1033\fs20 r-v\plain \f1\lang1033\fs20 ) Schriftraum 16\u215 \'d78,5. 29-32 Zeilen; auf 132\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20   3 Zeilen, Rest der Seite leer. Nachtr\u228 \'e4ge in B\u252 \'fccherkursiven bzw. Hybrida und Semihybrida verschiedener H\u228 \'e4nde, u. a. von Aicher, m\u246 \'f6glicherweise auch von Georg Ammon (vgl. \plain \f1\scaps\lang1033\fs20 Bischoff\plain \f1\lang1033\fs20 , St. Emmeram im Sp\u228 \'e4tmittelalter, S. 142 mit Anm. 162, dazu auch MBK 4/1, S. 184 mit Anm. 1). (133\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -141\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ) Schriftraum 15,5\u215 \'d79. 29-32  Zeilen. {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Bastarda}}\plain \f1\lang1033\fs20   bzw. {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cursiva libraria-formata}}\plain \f1\lang1033\fs20   von der Hand Konrad Pleystainers. Erg\u228 \'e4nzungen am Rand und am Ende von {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Laurentius Aicher}}\plain \f1\lang1033\fs20 , \u220 \'dcberschriften zu den jeweiligen Pulten in Textualis. Auf 133\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20   am Beginn des Kataloges rote Lombarde mit Punktverdickung.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red224\green224\blue224;\red255\green204\blue153;}

