\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -96\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Trojadichtung: \u8218 \'82Pergama flere volo\lquote  (= Carmen Buranum 101) und \u8218 \'82Viribus arte minis\lquote  (Anfang) cum commento}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Haupttext:\plain \f1\i\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Pergama flere volo}}\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24 ...\plain \f1\i\lang1033\fs24   \endash  \plain \f1\lang1033\fs24  (95\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) ...\plain \f1\i\lang1033\fs24   femina fetalis \plain \f1\lang1033\fs24  (!)\plain \f1\i\lang1033\fs24   femina plena malis / {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Auribus (!) arte meis Danaum datur Troija ruinis}}\plain \f1\i\lang1033\fs24  ... \endash ... raptam raptoris questa iacere thoris. {\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item historia Troijana feliciter finit metrica 1473o feria secunda ante festum sancte Marie Magdalene}}\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24  ((= 24. Juli 1473), folgt Rasur; Kommentar: \plain \f1\i\lang1033\fs24  Incipit historia troiana metrice\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 ... \endash ...\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  durcos vel thurcos vel turcos hodie vocari etc.\plain \f1\lang1033\fs24 , folgt Rasur, \plain \f1\i\lang1033\fs24  et est finis\plain \f1\lang1033\fs24  ; der Haupttext ist durchg\u228 \'e4ngig mit Interlinearglossen und Wortfolgeziffern f\u252 \'fcr den Schulgebrauch aufbereitet. Das Carmen Buranum 101 und das Trojagedicht \u8218 \'82Viribus arte minis\lquote  (h\u228 \'e4ufig Petrus Sanctonensis zugeschrieben) gehen direkt ineinander \u252 \'fcber. Sie sind oft zusammen \u252 \'fcberliefert, vgl. \plain \f1\scaps\lang1033\fs24 Hilka\plain \f1\lang1033\fs24  /\plain \f1\scaps\lang1033\fs24 Schumann\plain \f1\lang1033\fs24 , S. 144-145 (Sigle dieser Hs.: M\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 ). Die Abschrift ist ziemlich fehlerhaft, aber reich glossiert und kommentiert. Die Glossierung beginnt mit dem Titel \plain \f1\i\lang1033\fs24  historia troiana feliciter incipit\plain \f1\lang1033\fs24   und einer schematischen Auflistung der Hauptpersonen des Epos (\plain \f1\i\lang1033\fs24  Priamus\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24   Paris\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24   Hercula\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24   Menelaus\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24   Helena\plain \f1\lang1033\fs24 ). Das erste Gedicht ist weitgehend vollst\u228 \'e4ndig, das zweite bricht mit Vers 36 ab. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 Edition: Alfons \plain \f1\scaps\lang1033\fs20 Hilka\plain \f1\lang1033\fs20   / Otto \plain \f1\scaps\lang1033\fs20 Schumann\plain \f1\lang1033\fs20 , Carmina Burana. Bd. I/2. Heidelberg 1941, S. 139-160 (Pergama flere volo); Ed\u233 \'e9lestand \plain \f1\scaps\lang1033\fs20 du M\u233 \'e9ril\plain \f1\lang1033\fs20 , Po\u233 \'e9sies populaires latines ant\u233 \'e9rieures au douzi\u232 \'e8me si\u232 \'e8cle. Paris 1843, S. 400-405, hierzu bis S. 403 (Viribus arte minis). \endash  Vgl. \plain \f1\scaps\lang1033\fs20 Walther\plain \f1\lang1033\fs20 , Initia carminum 20582 (Viribus arte minis).}

