\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\scaps\lang1033\fs20 Sanftl\plain \f1\lang1033\fs20   I, p. 42f., 116, 303, 437f., 447, 522, 527f., 567, 572, 574, 576, 599f., 605, 607f., 650, 745, 747-749, 781, 788, 791, II, p. 1061, 1285-1288, III, p. 1504-1516, 1567, 1897 IV, p. 33f., 92, 207. \endash  \plain \f1\scaps\lang1033\fs20 Bischoff\plain \f1\lang1033\fs20 , St. Emmeram im Sp\u228 \'e4tmittelalter, S. 148 mit Anm. 193 und 195. \endash  \plain \f1\scaps\lang1033\fs20 D\plain \f1\scaps\lang1033\fs20 \u246 \'f6\plain \f1\scaps\lang1033\fs20 ring\plain \f1\lang1033\fs20 , Sultansbriefe, S. 54 (Sigle = M\u252 \'fc\plain \f1\sub\lang1033\fs20 16\plain \f1\lang1033\fs20 ).}

