\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Beatus vir qui non abijt in consilio (Ps 1,1). Ad intelligendam hystoriam breuiter perstringam}}\plain \f1\i\lang1033\fs24   de omnibus psalmis\plain \f1\lang1033\fs24  ... \endash ... \plain \f1\i\lang1033\fs24  Laudate dominum de celis\plain \f1\lang1033\fs24   (Ps 148,1). \plain \f1\i\lang1033\fs24  Abyssa dicuntur loca profunda in mari\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24  dicunt dracones magnas\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Et sic est finis titulorum\plain \f1\lang1033\fs24  ; folgt der Text von Ps 151: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Pusillus eram inter fratres meos}}\plain \f1\lang1033\fs24  ... \endash ... \plain \f1\i\lang1033\fs24  de filijs Israhel\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Hec David propheta\plain \f1\lang1033\fs24  ; folgen notae zu den Psalmen (aus dem Psalmenkommentar des Richard Rolle?): {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Queritur, quare scriptura psalmorum plus ceteris frequentetur in diuinis officijs}}\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24 ...\plain \f1\i\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nota, quod triplex est quinquagena psalmorum}}\plain \f1\lang1033\fs24  ... (vgl. Heinrich \plain \f1\scaps\lang1033\fs24 Mittendorff\plain \f1\lang1033\fs24 , Studien \u252 \'fcber Richard Rolle von Hampole unter besonderer Ber\u252 \'fccksichtigung seiner Psalmenkommentare. Magdeburg 1888, S. 29); darunter Merkverse zu den Psalmen: {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ter quinquagenos Dauid canit}}\plain \f1\lang1033\fs24  ... (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia carminum 19209).}

