\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sanctus Jeronimus in tractatu virorum illustrium scribit: Victorinus}}\plain \f1\i\lang1033\fs24   nacione\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  Aquitanicus calculator \plain \f1\lang1033\fs24 ... \endash ... \plain \f1\i\lang1033\fs24  die eademque luna\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  que primo passionis\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  ac\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  resurrectionis dominice anno facta est\plain \f1\lang1033\fs24 .
