\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Honorabili viro fratri religioso Iohanni de Capistrano sibi in Christo dilecto. Cum suis boni affectum}}\plain \f1\i\lang1033\fs24   animi\plain \f1\lang1033\fs24   (\plain \f1\i\lang1033\fs24  animi\plain \f1\lang1033\fs24   am Rand nachgetragen) ... \plain \f1\i\lang1033\fs24  Fama discurrente frequenter audiuimus \plain \f1\lang1033\fs24 ... \endash ... \plain \f1\i\lang1033\fs24  responso nuncciari per presentem\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Datum Sabbato ante exaltacionem sancte crucis anno quinquagesimo primo \plain \f1\lang1033\fs24  (= 11. September). \plain \f1\i\lang1033\fs24  Sequens scriptum manu propria exaratum\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24  Magister Johannes de Rokiczan\plain \f1\lang1033\fs24 .
