\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  156\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -237\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Augustinus de Urbino (?)}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De pugna spirituali (Quadragesimale de bello spirituali)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (156\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -237\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Quadragesimale bonum de bello spirituali\plain \f1\lang1033\fs24  <.\plain \f1\i\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cvm ieiunatis ... (Mt 6,16). Quando vita nostra sit continua pugna}}\plain \f1\lang1033\fs24  ... \endash ... \plain \f1\i\lang1033\fs24  Ecce magister\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  tua rogemus etc\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24  Expliciunt sermones de ewangelijs per 40\plain \f1\i\super\lang1033\fs24 mam\plain \f1\i\lang1033\fs24   de bello spirituali anno domini etc\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  LIIII in uigilia omnium sanctorum\plain \f1\lang1033\fs24   (= 31. Oktober 1454)<; 237\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24   leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
