\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -10\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Marinus Sanutus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistulae}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -4\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) 1. Brief: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In nomine domini nostri Iesu Christi ... Christianissimo principi ac victoriosissimo domino ... Licet presumptuosum appareat}}\plain \f1\lang1033\fs24  ... (an K\u246 \'f6nig {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Philipp VI. von Frankreich}}\plain \f1\lang1033\fs24 ); (4\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  -6\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) 2. Brief: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Serenissimo et excellentissimo domino meo karissimo domino Ludowico ducis Borboni ... Noscat vestra serenissima}}\plain \f1\i\lang1033\fs24   magnificiencia\plain \f1\lang1033\fs24  ... (an Herzog {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ludwig I. von Bourbon}}\plain \f1\lang1033\fs24 ); (6\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -7\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) 3. Brief: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sacre regie maiestati suo Ruberto ... Quoniam animus uerba diiudicat}}\plain \f1\lang1033\fs24  ... (an K\u246 \'f6nig {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Robert I. von Neapel}}\plain \f1\lang1033\fs24 ); (7\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -7\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) 4. Brief: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Reuerendis in Christo patribus, domino arciepiscopo Cantatis (!) ... Quoniam filij tenebrarum in generacione sua sunt prudenciores}}\plain \f1\lang1033\fs24  ... (von Bischof Petrus von Sebastopolis (Sochumi/Georgien) an die Bisch\u246 \'f6fe von England); (8\plain \f1\super\lang1033\fs24 ra-va\plain \f1\lang1033\fs24 ) 5. Brief: {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Serenissimo excellentissimo domino meo domino Wilhelmo ... Noscat vestra circumspecta prouidentia}}\plain \f1\lang1033\fs24  ... (an Graf {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Wilhelm III. von Holland}}\plain \f1\lang1033\fs24 ); 8\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24   leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Edition: Friedrich \plain \f1\scaps\lang1033\fs20 Kunstmann\plain \f1\lang1033\fs20 , Studien \u252 \'fcber Marino Sanudo den Aelteren. Mit einem Anhang seiner ungedruckten Briefe. M\u252 \'fcnchen 1855 (zuerst ver\u246 \'f6ffentlicht in: Abhandlungen der historischen Classe der k\u246 \'f6niglich bayerischen Akademie der Wissenschaften 7, 3. Abt. (1855), S. 693-819): 1. = Nr. VI, S. 103-112; 2. = Nr. VII, S. 112-117; 3. = Nr. VIII, S. 117f.; 4. = Nr. X, S. 121-123; 5. = Nr. IX, S. 119f. (nach dem Text dieser Hs.).}

