\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  156\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -161\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Satisfactiones peccatorum secundum \u8218 \'82Summam Iohannis\lquote }}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hic reperis has satisfactiones sicut ipse Iohannes in sua summa docet ... Hereticus}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Primo hereticus pie est recipiendus\plain \f1\lang1033\fs24  ... \endash ... \plain \f1\i\lang1033\fs24  3\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24   quod \plain \f1\lang1033\fs24  (!)\plain \f1\i\lang1033\fs24   habeat auctoritatem absoluendi. De illo 3\plain \f1\i\super\lang1033\fs24 o\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  vide lacius in tractatu magistri Henrici de Hassia etc.\plain \f1\lang1033\fs24  ; Rest der Seite und 161\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Parallel\u252 \'fcberlieferung: u. a. {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 14104}}\plain \f1\lang1033\fs20 , 299\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  -303\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 14113}}\plain \f1\lang1033\fs20 , 87\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20  -89\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20  ; Eichst\u228 \'e4tt, UB, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. st 266}}\plain \f1\lang1033\fs20 , 170\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20  -172\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20   ; Graz, UB, {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Ms. 1054}}\plain \f1\lang1033\fs20 , 66\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -70\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  ; Augsburg, StuSB, {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 2o Cod 356}}\plain \f1\lang1033\fs20 , 421\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  -423\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 . \endash  Vgl. \plain \f1\scaps\lang1033\fs20 Bloomfield\plain \f1\lang1033\fs20   2864. \endash  Die genannte \u8218 \'82Summa Iohannis\lquote  ist nicht bestimmbar, ein Textvergleich ergab weder mit dem Liber poenitentiarius des Johannes de Deo Hispanus noch mit der Summa confessorum des Johannes Friburgensis ausreichende \u220 \'dcbereinstimmungen.}

