\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -179\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Iacobus de Fladnitz}}\plain \f1\b\lang1033\fs24 :\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Expositio orationis dominicae, salutationis angelicae, symboli apostolorum}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -169\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Expositio orationis dominicae: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Pater noster, qui es in celis ... Titulus istius orationis est oratio dominica}}\plain \f1\lang1033\fs24  ...; (169\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -171\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Expositio salutationis angelicae: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ave Maria gratia plena ... A spiritu sancto sic factum est, ut post orationem}}\plain \f1\i\lang1033\fs24   dominicam\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  quo et deum patrem glorificatus\plain \f1\lang1033\fs24  ...; (171\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -179\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Expositio symboli apostolorum: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Credo in deum patrem ... Titulus huius fidei est simbolum apostolorum}}\plain \f1\lang1033\fs24  ... \endash ... \plain \f1\i\lang1033\fs24  quam nobis prestare dignetur Ihesus Christus dei filius cum patre et spiritu sancto vnus deus\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Parallel\u252 \'fcberlieferung: Melk, StiftsB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. 749}}\plain \f1\lang1033\fs20 , 353\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -366\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 . \endash  Zum Autor vgl. Paul \plain \f1\scaps\lang1033\fs20 Uiblein\plain \f1\lang1033\fs20 , Die Akten der Theologischen Fakult\u228 \'e4t der Universit\u228 \'e4t Wien 1396-1508. Bd. 2. Wien 1978, S. 651.}

