\uc1
\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\scaps\lang1033\fs20 Sanftl\plain \f1\lang1033\fs20   I, p. 113, 323, 527, 529, 579, 615, 742, 764, III, p. 1547, IV, p. 89, 226. \endash  \plain \f1\scaps\lang1033\fs20 Bischoff\plain \f1\lang1033\fs20 , St. Emmeram im Sp\u228 \'e4tmittelalter, S. 130 Anm. 90. \endash  Colophons 13336.}

