\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Themata sermonum}}\plain \f1\lang1033\fs24   (h\u228 \'e4ufig aus Nicolaus de Gorra, Sermones de tempore et de quadragesima): {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Misit [Initiale unvollst\u228 \'e4ndig] deus filium suum}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  \u8230 \'85 (Gal 4,4)}}\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Misit seruos uocare}}{\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  \u8230 \'85 (Mt 22,3)}}\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 3}}{\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs24\chcbpat17 a}}\plain \f1\lang1033\fs24\chcbpat17  (= Tria) {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 tanguntur}}{\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , }}{\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 que competunt predicatori}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Primo debet habere\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  predicandi\plain \f1\lang1033\fs24   \u8230 \'85; {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Erit (e vorgeschrieben) radix Iesse \u8230 \'85 (Rm 15,12). Quadruplici affeccione monet cor humanum}}\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  dolore\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  timore\plain \f1\lang1033\fs24   \u8230 \'85; {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ecce ego mitto angelum \u8230 \'85 (Mt 11,10). Si sol materialis habet stellam}}\plain \f1\lang1033\fs24   \u8230 \'85; (1\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) [{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 B]enedictus, qui uenit \u8230 \'85 (Mt 21,9). Contingit reddere malum pro bono}}\plain \f1\lang1033\fs24   \u8230 \'85; (2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  C\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  In die pasche\plain \f1\lang1033\fs24 . [{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 H]ec est dies \u8230 \'85 (Ps 117,24). In verbis istis duo notantur}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Primo solempnitas resurrectionis commendatur\plain \f1\lang1033\fs24   \u8230 \'85; (3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  Feria tercia in festo\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  pasche\plain \f1\lang1033\fs24 . [{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 D]eus suscitauit eum a mortuis. Act. 13 (Act 13,37). Licet inpossibile sit deuenire}}\plain \f1\i\lang1033\fs24   a\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  priuacione in habitum a morte ad vitam per naturam\plain \f1\lang1033\fs24   \u8230 \'85; (4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) endet: {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Qve est ista, que progreditur \u8230 \'85 (Ct 6,9). Considerare debemus}}\plain \f1\i\lang1033\fs24   gloriosissime virginis assumptionem\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  plenissima possessione\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Zu den Sermones, die Nicolaus de Gorra zugeschrieben werden k\u246 \'f6nnen vgl. \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Rep. 4, S. 255 Nr. 6, 12, 4, S. 262 Nr. 8.}

