\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f3\i\lang1024\fs24\chcbpat17 In metienda subtilissim\u281 \'ea inuentionis Ptolomei Wazzalchora}}\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  id est plana spera\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  quam\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  astrolabium uocitamus\plain \f1\lang1033\fs24   \u8230 \'85 \u8210 ? \u8230 \'85 \plain \f1\i\lang1033\fs24  alias debet notificare\plain \f1\lang1033\fs24  ; (83\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Raum f\u252 \'fcr Sterntabelle zu cap. VI freigelassen.
